/**
 * ⚠️ REGRA OBRIGATÓRIA AO ADICIONAR CURSOS NOVOS (aqui ou na tabela
 * `courses` do banco): todo card de curso exibe o LOGOTIPO da instituição
 * de ensino que oferece a bolsa gratuita. Para isso:
 *   - preencha `institutionLogo` com a URL do logotipo oficial; OU
 *   - garanta que a instituição tem o domínio oficial mapeado em
 *     `INSTITUTION_DOMAINS` (client/src/components/InstitutionLogo.tsx).
 * Sem uma das duas, o card cai no monograma de iniciais (fallback).
 * Use SEMPRE o mesmo nome de instituição já existente (o mapa é por nome).
 *
 * ARTE DE CAPA (`coverImage`): cada curso pode ter uma arte gerada por IA
 * baseada no tema do curso. Padrão: imagem SEM texto/letras/logos, tema do
 * curso na paleta oficial da marca (verde floresta escuro de fundo,
 * filamentos Azul Oceano #008CBF, acentos Amarelo Sol #F4C42E), paisagem
 * 3:2, salva otimizada em client/public/cursos/<slug>.webp (~1000px de
 * largura, WebP q82, ideal < 100 KB) e referenciada como
 * coverImage: "/cursos/<slug>.webp". Sem coverImage o card usa o gradiente
 * da categoria (fallback). Exemplo de referência: machine-learning-stanford.
 */
export interface CourseDemo {
  id: number;
  slug: string;
  title: string;
  description: string | null;
  institution: string;
  institutionLogo: string | null;
  platform: string | null;
  platformUrl: string;
  category: string;
  duration: string | null;
  level: "iniciante" | "intermediario" | "avancado";
  coverImage: string | null;
  tags: string | null;
  featured: boolean;
  active: boolean;
  createdAt: Date;
}

